	@Test
	void omissionAndHiddenGroupDenyCanonicalPagesEvenWhenVisibleItemLinksToOne() {
		Properties properties = new Properties();
		properties.setProperty("menu.items", "query-shortcut,summary,update,add");
		properties.setProperty("menu.groups", "server,explore,modify,system");
		properties.setProperty("menu.item.query-shortcut.href", "/query");
		properties.setProperty("menu.item.query-shortcut.group", "server");
		properties.setProperty("menu.group.server.visible", "true");
		properties.setProperty("menu.group.explore.visible", "false");
		properties.setProperty("menu.group.modify.visible", "true");
		properties.setProperty("menu.item.add.visible", "false");

		WorkbenchPolicy policy = WorkbenchPolicy.fromProperties(properties, Set.of("query-shortcut"));

		assertThat(policy.getVisibleMenuItemIds()).contains("query-shortcut");
		assertThat(policy.isRouteAllowed("/repositories/example/query")).isFalse();
		assertThat(policy.isRouteAllowed("/repositories/example/summary")).isFalse();
		assertThat(policy.isRouteAllowed("/repositories/example/update")).isTrue();
		assertThat(policy.isRouteAllowed("/repositories/example/add")).isFalse();
		assertThat(policy.isRouteAllowed("/repositories/example/namespaces")).isFalse();
		assertThat(policy.isRouteAllowed("/repositories/example/_internal/namespaces")).isTrue();
		assertThat(policy.isRouteAllowed("/repositories/example/info")).isTrue();
	}

