	@Test
	void builtInQueryFeatureIdsAreStableImmutableAndEagerlyValidated() {
		Set<String> expected = BUILT_IN_QUERY_FEATURE_IDS;
		WorkbenchPolicy defaults = WorkbenchPolicy.fromProperties(new Properties(), Set.of());
		assertThat(expected).hasSize(47);
		assertThat(defaults.getQueryFeatureIds()).containsExactlyInAnyOrderElementsOf(expected);

		Properties properties = new Properties();
		for (String id : expected) {
			properties.setProperty("query.feature." + id + ".enabled", "false");
		}

		WorkbenchPolicy policy = WorkbenchPolicy.fromProperties(properties, Set.of());

		assertThat(policy.getQueryFeatureIds()).containsExactlyInAnyOrderElementsOf(expected);
		assertThatThrownBy(() -> policy.getQueryFeatureIds().add("injected-feature"))
				.isInstanceOf(UnsupportedOperationException.class);
		for (String id : expected) {
			assertThat(policy.isQueryFeatureEnabled(id)).as(id).isFalse();
		}
	}

